<section id="settings" class="grid two"><article class="card"><div class="card-heading"><span class="feature-icon green"><?= $icon('qr') ?></span><div><h2>微信小程序</h2><p class="muted">配置扫码登录服务</p></div></div><form method="post" action="/admin/settings"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="kind" value="wechat"><label>AppID<input name="app_id" value="<?= $e($wx['app_id']??'wx4ec45155a93041cc') ?>" required></label><label>AppSecret<input name="secret" type="password" autocomplete="new-password" placeholder="留空保留已配置密钥"></label><label>页面路径<input name="page" value="<?= $e($wx['page']??'pages/account-confirm/index') ?>" required></label><label>版本<select name="env"><?php foreach(['release'=>'正式版','trial'=>'体验版','develop'=>'开发版'] as $value=>$label): ?><option value="<?= $value ?>" <?= ($wx['env']??'release')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></label><label class="check"><input type="checkbox" name="enabled" value="1" <?= !empty($wx['enabled'])?'checked':'' ?>>启用微信扫码</label><button>保存微信配置</button></form></article><article class="card"><div class="card-heading"><span class="feature-icon"><?= $icon('mail') ?></span><div><h2>邮箱验证码</h2><p class="muted">配置验证码邮件服务</p></div></div><form method="post" action="/admin/settings"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="kind" value="smtp"><label>SMTP 主机<input name="host" value="<?= $e($smtp['host']??'') ?>" required></label><label>端口<input name="port" type="number" value="<?= $e($smtp['port']??587) ?>" required></label><label>加密<select name="security"><option value="tls" <?= ($smtp['security']??'tls')==='tls'?'selected':'' ?>>STARTTLS（通常 587）</option><option value="ssl" <?= ($smtp['security']??'tls')==='ssl'?'selected':'' ?>>SSL/TLS（通常 465）</option></select></label><label>用户名<input name="username" value="<?= $e($smtp['username']??'') ?>"></label><label>密码 / 授权码<input name="password" type="password" autocomplete="new-password" placeholder="留空保留已配置密码"></label><label>发件邮箱<input name="from" type="email" value="<?= $e($smtp['from']??'') ?>" required></label><button>保存邮件配置</button></form></article></section>